56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Syntactic validation for an owner email: a non-empty local part, an '@', and a dotted domain
69	     * whose top-level label is at least two letters. Deliberately conservative so plainly malformed
70	     * input (e.g. a value without an '@') is rejected.
71	     */
72	    private static final Pattern EMAIL_PATTERN =
73	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        normalizeAddress(ownerFieldsDto);
122	        rejectBlankOwnerFields(ownerFieldsDto);
123	        normalizeTelephone(ownerFieldsDto);
124	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
125	        rejectDuplicateHousehold(ownerFieldsDto);
126	        normalizeEmail(ownerFieldsDto);
127	        HttpHeaders headers = new HttpHeaders();
128	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
129	        if (owner.getRegistrationDate() == null) {
130	            owner.setRegistrationDate(LocalDate.now());
131	        }
132	        owner.setHouseholdId(HouseholdNormalizer.toHouseholdId(owner.getLastName(), owner.getAddress()));
133	        this.clinicService.saveOwner(owner);
134	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
135	        headers.setLocation(UriComponentsBuilder.newInstance()
136	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
137	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
143	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
144	        if (currentOwner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        currentOwner.setAddress(ownerFieldsDto.getAddress());
148	        currentOwner.setCity(ownerFieldsDto.getCity());
149	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
150	        currentOwner.setLastName(ownerFieldsDto.getLastName());
151	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
152	        normalizeEmail(ownerFieldsDto);
153	        currentOwner.setEmail(ownerFieldsDto.getEmail());
154	        currentOwner.setHouseholdId(
155	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
156	        this.clinicService.saveOwner(currentOwner);
157	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Transactional
162	    @Override
163	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
164	        Owner owner = this.clinicService.findOwnerById(ownerId);
165	        if (owner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        this.clinicService.deleteOwner(owner);
169	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
175	        Owner owner = this.clinicService.findOwnerById(ownerId);
176	        if (owner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        HttpHeaders headers = new HttpHeaders();
180	        Pet pet = petMapper.toPet(petFieldsDto);
181	        owner.setId(ownerId);
182	        pet.setOwner(owner);
183	        pet.getType().setName(null);
184	        this.clinicService.savePet(pet);
185	        PetDto petDto = petMapper.toPetDto(pet);
186	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
187	            .buildAndExpand(pet.getId()).toUri());
188	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
194	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
195	        if (currentOwner != null) {
196	            Pet currentPet = this.clinicService.findPetById(petId);
197	            if (currentPet != null) {
198	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
199	                currentPet.setName(petFieldsDto.getName());
200	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
201	                this.clinicService.savePet(currentPet);
202	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
203	            }
204	        }
205	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
211	        HttpHeaders headers = new HttpHeaders();
212	        Visit visit = visitMapper.toVisit(visitFieldsDto);
213	        Pet pet = new Pet();
214	        pet.setId(petId);
215	        visit.setPet(pet);
216	        this.clinicService.saveVisit(visit);
217	        VisitDto visitDto = visitMapper.toVisitDto(visit);
218	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
219	            .buildAndExpand(visit.getId()).toUri());
220	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
221	    }
222	
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
227	        Owner owner = this.clinicService.findOwnerById(ownerId);
228	        if (owner != null) {
229	            Pet pet = owner.getPet(petId);
230	            if (pet != null) {
231	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
232	            }
233	        }
234	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	    }
236	
237	    /**
238	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
239	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
240	     * the request body already rejects null and empty values, but permits whitespace-only strings
241	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
242	     * that gap so every required field must carry a non-blank value.
243	     *
244	     * @param ownerFieldsDto the submitted owner fields
245	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
246	     */
247	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
248	        List<String> missing = new ArrayList<>();
249	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
250	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
251	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
252	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
253	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
254	        if (!missing.isEmpty()) {
255	            throw new InvalidOwnerFieldsException(missing);
256	        }
257	    }
258	
259	    private void addIfBlank(List<String> missing, String fieldName, String value) {
260	        if (value == null || value.isBlank()) {
261	            missing.add(fieldName);
262	        }
263	    }
264	
265	    /**
266	     * Normalizes the submitted {@code address} on create to its canonical form (see
267	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
268	     * stored and returned, and the form every later address comparison (the required-field check,
269	     * household duplicate detection and the shared household id) is judged on. A null address is left
270	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
271	     * after normalization likewise reduces to the empty string and is rejected there.
272	     *
273	     * @param ownerFieldsDto the submitted owner fields
274	     */
275	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
276	        String address = ownerFieldsDto.getAddress();
277	        if (address == null) {
278	            return;
279	        }
280	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
281	    }
282	
283	    /**
284	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
285	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
286	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
287	     * {@code 400 Bad Request}.
288	     *
289	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
290	     *                       {@link #rejectBlankOwnerFields} having already run)
291	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
292	     */
293	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
294	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
295	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
296	        ownerFieldsDto.setTelephone(normalized);
297	    }
298	
299	    /**
300	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
301	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
302	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
303	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
304	     *
305	     * @param ownerFieldsDto the submitted owner fields
306	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
307	     */
308	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
309	        String email = ownerFieldsDto.getEmail();
310	        if (email == null || email.isBlank()) {
311	            return;
312	        }
313	        email = email.trim();
314	        if (!EMAIL_PATTERN.matcher(email).matches()) {
315	            throw new InvalidOwnerFieldsException(List.of("email"));
316	        }
317	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
318	    }
319	
320	    /**
321	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
322	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
323	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
324	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
325	     *
326	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
327	     *                            {@link #normalizeTelephone}
328	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
329	     */
330	    private void rejectDuplicateTelephone(String normalizedTelephone) {
331	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
332	        boolean inUse = this.clinicService.findAllOwners().stream()
333	            .map(Owner::getTelephone)
334	            .filter(Objects::nonNull)
335	            .map(TelephoneNormalizer::toComparisonKey)
336	            .anyMatch(comparisonKey::equals);
337	        if (inUse) {
338	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
339	        }
340	    }
341	
342	    /**
343	     * Rejects creating an owner who shares a household with any existing owner, unless the request
344	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
345	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
346	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
347	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
348	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
349	     *
350	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
351	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
352	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
353	     *                                          request did not opt in with {@code sharesHousehold}
354	     */
355	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
356	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
357	            return;
358	        }
359	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
360	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
361	        boolean inUse = this.clinicService.findAllOwners().stream()
362	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
363	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
364	            .anyMatch(comparisonKey::equals);
365	        if (inUse) {
366	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
367	        }
368	    }
369	}
